'use strict';

const test = require('node:test');
const assert = require('node:assert');

const { formatFor, availableFormats } = require('../src/exporter');

const run = {
  id: 'run-41',
  columns: ['region', 'orders'],
  rows: [
    { orders: 12, region: 'north' },
    { orders: 7, region: 'south' },
  ],
};

test('json export honours the run column order', () => {
  const parsed = JSON.parse(formatFor('json', run));
  assert.deepStrictEqual(Object.keys(parsed.rows[0]), ['region', 'orders']);
});

test('an unknown format is refused with the format named', () => {
  assert.throws(() => formatFor('pdf', run), /unsupported export kind: pdf/);
});

test('available formats lists what the exporter implements', () => {
  assert.deepStrictEqual(availableFormats(), ['json', 'csv']);
});

test('csv export leads with the declared columns and keeps their order (B-6)', () => {
  assert.strictEqual(formatFor('csv', run), 'region,orders\r\nnorth,12\r\nsouth,7\r\n');
});

test('csv export quotes only fields that need it, doubling inner quotes (B-6)', () => {
  const awkward = {
    id: 'run-42',
    columns: ['name', 'note', 'count'],
    rows: [{ name: 'a,b', note: 'said "hi"', count: 3 }, { name: 'plain', note: 'line\nbreak', count: null }],
  };
  assert.strictEqual(
    formatFor('csv', awkward),
    'name,note,count\r\n"a,b","said ""hi""",3\r\nplain,"line\nbreak",\r\n',
  );
});

test('csv export never re-executes: it reads only what the run stores (B-3)', () => {
  const csv = formatFor('csv', { id: 'run-43', columns: ['x'], rows: [] });
  assert.strictEqual(csv, 'x\r\n');
});

```

