      'north,plain,12\r\n' +
      '"south, east","says ""hi""",7\r\n' +
      'west,"two\nlines",\r\n',
  );
});

test('csv export of a run with no rows is the header alone', () => {
  assert.strictEqual(formatFor('csv', { id: 'run-0', columns: ['a', 'b'], rows: [] }), 'a,b\r\n');
});

