    formatFor('csv', run),
    'region,orders\r\nnorth,12\r\nsouth,7\r\n'
  );
});

test('csv export quotes only fields that need it and doubles embedded quotes', () => {
  const tricky = {
    id: 'run-42',
    columns: ['name', 'note'],
    rows: [
      { name: 'Ada, Lovelace', note: 'said "hi"' },
      { name: 'plain', note: 'two\nlines' },
    ],
  };
  assert.strictEqual(
    formatFor('csv', tricky),
    'name,note\r\n"Ada, Lovelace","said ""hi"""\r\nplain,"two\nlines"\r\n'
  );
});

test('csv export writes null and undefined as empty fields', () => {
