### product/specs/reports.md
```
# reports — spec

> Status: shipped v0.3.0 · v0.4.0 in progress · [ROADMAP](../ROADMAP.md)

## Purpose

Run a saved query, keep the result, and hand it back in a format the caller can
use. A report is the durable answer to a question somebody asked once and will
ask again.

## Scope

- **In scope:** saved queries, runs, schedules, and the export surface over a
  stored run.
- **Out of scope:** the query language itself; charting; anything that mutates a
  run after it is written.

## Behavior

- **B-1 A run is immutable.** Once a run is written its rows never change; a
  re-execution creates a new run with a new id.
- **B-2 A run carries its column order.** Column order is stored with the run and
  is part of what the run means.
- **B-3 Export never re-executes.** An export reads a stored run and formats it;
  it never touches the datasource.
- **B-4 JSON export is available over the API.** A caller can pull any stored run
  as JSON, with the run's declared column order preserved in the object keys.
- **B-5 An unknown export format is refused loudly.** Asking for a format the
  tool does not implement fails with the format named in the error, never with a
  silent fallback.
- **B-6 CSV export is available over the API.** A caller can pull any stored run
  as CSV the same way as JSON. The first record is a header of the run's declared
  columns; each row follows as one record in that order. Fields follow RFC 4180:
  a field containing a comma, a double quote, or a line break is wrapped in
  double quotes with inner quotes doubled, records end in CRLF, and a null or
  undefined value is an empty field. `csv` is listed among the available formats.

## Decisions

- **D-001** — a report is a saved query plus an immutable run.
- **D-003** — export is a pure function of a stored run.
- **D-004** — runs carry declared column order.
- **D-005** — CSV export is 0.4.0; format details as B-6.

```

### src/exporter.js
```
'use strict';

/**
 * Export a stored run. Formatting only — an exporter never re-executes the
 * query behind the run (spec reports.md B-3).
 */

const FORMATS = ['json', 'csv'];

function formatFor(kind, run) {
  if (kind === 'json') return toJson(run);
  if (kind === 'csv') return toCsv(run);
  throw new Error(`unsupported export kind: ${kind}`);
}

function toJson(run) {
  const rows = run.rows.map((row) => {
    const ordered = {};
    for (const column of run.columns) ordered[column] = row[column];
    return ordered;
  });
  return JSON.stringify({ runId: run.id, columns: run.columns, rows }, null, 2);
}

// RFC 4180 (spec reports.md B-6): header record from the run's declared
// columns, one record per row in that order, CRLF record ends, fields quoted
// only when they contain a comma, a double quote, or a line break.
const CRLF = '\r\n';

function toCsv(run) {
  const header = run.columns.map(csvField).join(',');
  const records = run.rows.map((row) =>
    run.columns.map((column) => csvField(row[column])).join(','),
  );
  return [header, ...records].map((record) => record + CRLF).join('');
}

function csvField(value) {
  if (value === null || value === undefined) return '';
  const text = typeof value === 'object' ? JSON.stringify(value) : String(value);
  return /[",\r\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
}

function availableFormats() {
  return FORMATS.slice();
}

module.exports = { formatFor, toJson, toCsv, availableFormats };

```

### test/exporter.test.js
```
'use strict';

const test = require('node:test');
const assert = require('node:assert');

const { formatFor, availableFormats } = require('../src/exporter');

const run = {
  id: 'run-41',
  columns: ['region', 'orders'],
  rows: [
    { orders: 12, region: 'north' },
    { orders: 7, region: 'south' },
  ],
};

test('json export honours the run column order', () => {
  const parsed = JSON.parse(formatFor('json', run));
  assert.deepStrictEqual(Object.keys(parsed.rows[0]), ['region', 'orders']);
});

test('an unknown format is refused with the format named', () => {
  assert.throws(() => formatFor('pdf', run), /unsupported export kind: pdf/);
});

test('available formats lists what the exporter implements', () => {
  assert.deepStrictEqual(availableFormats(), ['json', 'csv']);
});

test('csv export is a header of the declared columns, then one record per row (B-6)', () => {
  const csv = formatFor('csv', run);
  assert.strictEqual(csv, 'region,orders\r\nnorth,12\r\nsouth,7\r\n');
});

test('csv export quotes per RFC 4180 and renders null as empty (B-6)', () => {
  const awkward = {
    id: 'run-42',
    columns: ['name', 'note', 'count'],
    rows: [
      { name: 'a, b', note: 'say "hi"', count: 0 },
      { name: 'line\nbreak', note: null, count: undefined },
    ],
  };
  assert.strictEqual(
    formatFor('csv', awkward),
    'name,note,count\r\n"a, b","say ""hi""",0\r\n"line\nbreak",,\r\n',
  );
});

test('csv export honours the run column order, not the row key order (B-6, D-004)', () => {
  const swapped = { ...run, columns: ['orders', 'region'] };
  assert.strictEqual(formatFor('csv', swapped).split('\r\n')[0], 'orders,region');
});

